function encodeCp932(text) {
  const bytes = [];
  const unsupported = [];
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp <= 0x7F) {
      bytes.push(cp);
      continue;
    }
    const mapped = CP932_MAP[ch];
    if (!mapped) {
      unsupported.push(ch);
      continue;
    }
    bytes.push(...mapped);
  }
  if (unsupported.length) {
    return { bytes: null, unsupported: [...new Set(unsupported)] };
  }
  return { bytes: new Uint8Array(bytes), unsupported: [] };
}
